import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sources = [
  "js/numeric.js",
  "js/formula-registry.js",
  "js/formulas.js",
  "js/effect-registry.js",
  "js/effect-engine.js",
  "js/effect-system.js",
  "js/stat-resolver.js",
  "js/audit-logger.js",
  "js/component-registry.js",
  "js/state.js",
  "js/save-system.js",
  "js/engine.js",
  "js/offline-progress.js",
  "js/ui-tooltip-content.js",
  "js/ui.js",
  "js/main.js",
];

function convertModuleToScript(source) {
  return source
    .replace(/^import\s+[\s\S]*?from\s+["'][^"']+["'];\r?\n/gm, "")
    .replace(/^export\s+/gm, "");
}

const config = JSON.parse(
  await readFile(path.join(root, "config/game-config.json"), "utf8"),
);

const news = JSON.parse(
  await readFile(path.join(root, "content/news.json"), "utf8"),
);

const decimalRuntime = await readFile(
  path.join(root, "node_modules/break_eternity.js/dist/break_eternity.js"),
  "utf8",
);

const sections = [];
for (const sourcePath of sources) {
  const source = await readFile(path.join(root, sourcePath), "utf8");
  sections.push(
    `\n// ---- ${sourcePath} ----\n${convertModuleToScript(source)}`,
  );
}

const bundle = `/* Generated by tools/build-bundle.mjs. Do not edit directly. */
${decimalRuntime}
(() => {
  "use strict";
  const Decimal = globalThis.Decimal || (typeof window !== "undefined" ? window.Decimal : null) || (typeof module !== "undefined" && module.exports ? module.exports : null);
  globalThis.Decimal = Decimal;
  globalThis.__TES_GAME_CONFIG__ = ${JSON.stringify(config, null, 2)};
  globalThis.__TES_NEWS__ = ${JSON.stringify(news, null, 2)};
${sections.join("\n")}
})();
`;

await writeFile(path.join(root, "js/game.bundle.js"), bundle, "utf8");
console.log("Generated js/game.bundle.js");
